  const sum = (rows, key, mo) => rows.filter(r => r.mo === mo).reduce((s, r) => s + (r[key] || 0), 0);
  const total = fm.map(m => { const p50 = sum(fut, "p50", m), sd = Math.sqrt(sum(fut, "var_q", m)) / 2.56, v = sum(fut, "val", m), sdv = Math.sqrt(sum(fut, "var_v", m)) / 2.56; return { month: m, p50: Math.round(p50), p10: Math.max(0, Math.round(p50 - 1.28 * sd)), p90: Math.round(p50 + 1.28 * sd), value_p50_idr: Math.round(v), value_p10_idr: Math.max(0, Math.round(v - 1.28 * sdv)), value_p90_idr: Math.round(v + 1.28 * sdv), campaign: hi.has(m) }; });
  const history = months.map(m => ({ month: m, qty: Math.round(sum(hist, "qty", m)), value_idr: Math.round(sum(hist, "val", m)) }));
  const byCrit = crits.map(c => ({ crit: c, history: months.map(m => Math.round((hist.find(r => r.mo === m && r.crit === c) || { qty: 0 }).qty)), forecast: fm.map(m => Math.round((fut.find(r => r.mo === m && r.crit === c) || { p50: 0 }).p50)), history_value: months.map(m => Math.round((hist.find(r => r.mo === m && r.crit === c) || { val: 0 }).val)), forecast_value: fm.map(m => Math.round((fut.find(r => r.mo === m && r.crit === c) || { val: 0 }).val)) }));
  const last12 = history.slice(-12), l12q = last12.reduce((s, x) => s + x.qty, 0), l12v = last12.reduce((s, x) => s + x.value_idr, 0), n12q = total.reduce((s, x) => s + x.p50, 0), n12v = total.reduce((s, x) => s + x.value_p50_idr, 0);
  const priced = one(db, "select sum(unit_price_idr is not null) a, count(*) b from part_profile where months_active>0");
  const recent = history.slice(-7), run = Math.round(recent.reduce((s, x) => s + x.qty, 0) / recent.length), base = total.filter(x => !x.campaign), baseRun = Math.round(base.reduce((s, x) => s + x.p50, 0) / Math.max(1, base.length));
