  const sets = rows.filter(r => r.cmin > 0), up = sets.filter(r => r.dmin > r.cmin).length, down = sets.filter(r => r.dmin < r.cmin).length, bothInfo = sets.length;
  const dist = ["erratic", "lumpy", "intermittent", "smooth"].map(k => { const a = rows.filter(r => r.cls === k && r.ratio != null).map(r => r.ratio); return { class: k, parts: a.length, p10: R(pct(a, .1), 2), median: R(median(a), 2), p90: R(pct(a, .9), 2) }; });
